<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import api from './api'
const token = ref(localStorage.getItem('hospital_token') || '')
const user = ref(JSON.parse(localStorage.getItem('hospital_user') || 'null'))
const active = ref('overview'), busy = ref(false), error = ref(''), notice = ref('')
const doctors = ref([]), departments = ref([]), patients = ref([]), appointments = ref([]), myDoctor = ref(null), availability = ref([]), myPatient = ref(null)
const loginForm = reactive({ email: '', password: '' })
const registerForm = reactive({ full_name: '', email: '', phone: '', password: '' })
const appointmentForm = reactive({ doctor_id: '', scheduled_at: '', reason: '' })
const departmentForm = reactive({ name: '', description: '' })
const doctorForm = reactive({ full_name: '', specialization: '', phone: '', department_id: '', account_email: '', account_password: '' })
const treatmentForm = reactive({ diagnosis: '', prescription: '', notes: '' })
const availabilityForm = reactive({ date: '', start_time: '09:00', end_time: '12:00' })
const profileForm = reactive({ full_name: '', phone: '', date_of_birth: '' })
const treatmentAppointment = ref(null), treatmentRecords = ref([])
const editingDepartment = ref(null), departmentEdit = reactive({ name: '', description: '' })
const editingDoctor = ref(null), doctorEdit = reactive({ full_name: '', specialization: '', phone: '', department_id: '', available: true })
const isAdmin = computed(() => user.value?.role === 'admin' || user.value?.roles?.includes('admin'))
const isDoctor = computed(() => user.value?.role === 'doctor' || user.value?.roles?.includes('doctor'))
const canTreat = computed(() => isAdmin.value || isDoctor.value)
const nav = computed(() => [{id:'overview',label:'Overview'},{id:'doctors',label:'Doctors'},{id:'appointments',label:'Appointments'}, ...(isDoctor.value?[{id:'availability',label:'My availability'}]:[]), ...(isAdmin.value?[{id:'patients',label:'Patients'},{id:'departments',label:'Departments'}]:[]), ...(user.value?.role==='patient'||user.value?.roles?.includes('patient')?[{id:'profile',label:'My profile'}]:[])])
function flash(message, isError=false) { error.value=isError?message:''; notice.value=isError?'':message; setTimeout(()=>{error.value='';notice.value=''},4500) }
async function loadAll(){ if(!token.value)return; busy.value=true; try { const [d,de,a]=await Promise.all([api.get('/doctors'),api.get('/departments'),api.get('/appointments')]); doctors.value=d.data;departments.value=de.data;appointments.value=a.data; if(isAdmin.value){patients.value=(await api.get('/patients')).data} if(isDoctor.value){const mine=await api.get('/doctors/me');myDoctor.value=mine.data;availability.value=(await api.get(`/doctors/${mine.data.id}/availability`)).data} if(user.value?.role==='patient'||user.value?.roles?.includes('patient')){const me=await api.get('/patients/me');myPatient.value=me.data;Object.assign(profileForm,{full_name:me.data.full_name||'',phone:me.data.phone||'',date_of_birth:me.data.date_of_birth||''})} } catch(e){flash(e.response?.data?.message||'Could not load data. Check that the backend is running.',true)} finally{busy.value=false} }
async function login(){busy.value=true;try{const {data}=await api.post('/auth/login',loginForm);token.value=data.token;user.value={...data.user,roles:[data.user.role]};localStorage.setItem('hospital_token',token.value);localStorage.setItem('hospital_user',JSON.stringify(user.value));active.value='overview';await loadAll();flash('Welcome back, '+user.value.full_name)}catch(e){flash(e.response?.data?.message||'Login failed',true)}finally{busy.value=false}}
async function register(){busy.value=true;try{await api.post('/auth/register',registerForm);loginForm.email=registerForm.email;loginForm.password=registerForm.password;await login()}catch(e){flash(e.response?.data?.message||'Registration failed',true)}finally{busy.value=false}}
async function logout(){try{await api.post('/auth/logout')}catch{};localStorage.removeItem('hospital_token');localStorage.removeItem('hospital_user');token.value='';user.value=null;appointments.value=[];active.value='overview'}
async function bookAppointment(){try{await api.post('/appointments',{doctor_id:Number(appointmentForm.doctor_id),scheduled_at:new Date(appointmentForm.scheduled_at).toISOString().slice(0,16),reason:appointmentForm.reason});appointmentForm.doctor_id='';appointmentForm.scheduled_at='';appointmentForm.reason='';await loadAll();flash('Appointment booked')}catch(e){flash(e.response?.data?.message||'Could not book appointment',true)}}
async function updateAppointment(a,status){try{await api.put(`/appointments/${a.id}`,{status});await loadAll();flash('Appointment updated')}catch(e){flash(e.response?.data?.message||'Could not update appointment',true)}}
async function addDepartment(){try{await api.post('/departments',departmentForm);departmentForm.name='';departmentForm.description='';await loadAll();flash('Department created')}catch(e){flash(e.response?.data?.message||'Could not create department',true)}}
async function deleteDepartment(d){if(!confirm(`Delete ${d.name}?`))return;try{await api.delete(`/departments/${d.id}`);await loadAll();flash('Department deleted')}catch(e){flash(e.response?.data?.message||'Could not delete department',true)}}
async function addDoctor(){try{const {data}=await api.post('/doctors',{...doctorForm,department_id:doctorForm.department_id?Number(doctorForm.department_id):null});Object.assign(doctorForm,{full_name:'',specialization:'',phone:'',department_id:'',account_email:'',account_password:''});await loadAll();flash(data.login_account_created?'Doctor added with a login account':'Doctor added; no login account was created')}catch(e){flash(e.response?.data?.message||'Could not add doctor',true)}}
async function openTreatment(a){treatmentAppointment.value=a;treatmentRecords.value=[];Object.assign(treatmentForm,{diagnosis:'',prescription:'',notes:''});try{const {data}=await api.get(`/appointments/${a.id}/treatments`);treatmentRecords.value=data}catch(e){flash(e.response?.data?.message||'Could not load treatment history',true)}}
async function saveTreatment(){if(!treatmentAppointment.value)return;try{await api.post(`/appointments/${treatmentAppointment.value.id}/treatments`,treatmentForm);await openTreatment(treatmentAppointment.value);await loadAll();flash('Treatment record saved')}catch(e){flash(e.response?.data?.message||'Could not save treatment record',true)}}
async function addAvailability(){if(!myDoctor.value)return;try{await api.post(`/doctors/${myDoctor.value.id}/availability`,availabilityForm);availability.value=(await api.get(`/doctors/${myDoctor.value.id}/availability`)).data;flash('Availability added')}catch(e){flash(e.response?.data?.message||'Could not add availability',true)}}
async function deleteAvailability(slot){if(!myDoctor.value||!confirm('Remove this availability window?'))return;try{await api.delete(`/doctors/${myDoctor.value.id}/availability/${slot.id}`);availability.value=(await api.get(`/doctors/${myDoctor.value.id}/availability`)).data;flash('Availability removed')}catch(e){flash(e.response?.data?.message||'Could not remove availability',true)}}
async function saveProfile(){try{const {data}=await api.put('/patients/me',profileForm);myPatient.value=data;user.value={...user.value,full_name:data.full_name};localStorage.setItem('hospital_user',JSON.stringify(user.value));flash('Profile updated')}catch(e){flash(e.response?.data?.message||'Could not update profile',true)}}
async function deleteDoctor(d){if(!confirm(`Delete ${d.full_name}?`))return;try{await api.delete(`/doctors/${d.id}`);await loadAll();flash('Doctor deleted')}catch(e){flash(e.response?.data?.message||'Could not delete doctor',true)}}
async function deletePatient(p){if(!confirm(`Delete patient ${p.full_name}?`))return;try{await api.delete(`/patients/${p.id}`);await loadAll();flash('Patient deleted')}catch(e){flash(e.response?.data?.message||'Could not delete patient',true)}}
function startEditDepartment(d){editingDepartment.value=d.id;Object.assign(departmentEdit,{name:d.name,description:d.description||''})}
async function saveDepartment(d){try{await api.put(`/departments/${d.id}`,{name:departmentEdit.name,description:departmentEdit.description});editingDepartment.value=null;await loadAll();flash('Department updated')}catch(e){flash(e.response?.data?.message||'Could not update department',true)}}
function startEditDoctor(d){editingDoctor.value=d.id;Object.assign(doctorEdit,{full_name:d.full_name,specialization:d.specialization,phone:d.phone||'',department_id:d.department_id||'',available:d.available})}
async function saveDoctor(d){try{await api.put(`/doctors/${d.id}`,{...doctorEdit,department_id:doctorEdit.department_id?Number(doctorEdit.department_id):null});editingDoctor.value=null;await loadAll();flash('Doctor updated')}catch(e){flash(e.response?.data?.message||'Could not update doctor',true)}}
async function runReminders(){try{const {data}=await api.post('/reminders/run');flash(data.message)}catch(e){flash(e.response?.data?.message||'Could not send reminders',true)}}
onMounted(async()=>{if(token.value){try{const {data}=await api.get('/auth/me');user.value={...data,role:data.roles?.[0]};localStorage.setItem('hospital_user',JSON.stringify(user.value));await loadAll()}catch{await logout()}}})
</script>
<template>
  <main v-if="!token" class="auth-shell"><section class="auth-art"><div class="brand"><span class="brand-mark">✚</span> CarePoint</div><div class="art-copy"><p class="eyebrow">CARE THAT CONNECTS</p><h1>Better care.<br><em>One connected</em><br>hospital.</h1><p>Manage appointments, discover specialists and coordinate care in one secure workspace.</p><div class="trust-row"><span>● Patient-first</span><span>● Secure access</span><span>● Connected teams</span></div></div><div class="art-foot">A calmer way to manage care.</div></section><section class="auth-panel"><div class="mobile-brand brand"><span class="brand-mark">✚</span> CarePoint</div><div class="auth-card"><p class="eyebrow">WELCOME TO CAREPOINT</p><h2>Sign in to your workspace</h2><p class="muted">Use your hospital account to continue.</p><form @submit.prevent="login"><label>Email address</label><input v-model="loginForm.email" type="email" required placeholder="you@hospital.com"><label>Password</label><input v-model="loginForm.password" type="password" required placeholder="Enter your password"><button class="primary full" :disabled="busy">{{busy?'Please wait…':'Sign in securely'}} <span>→</span></button></form><details class="register-box"><summary>New patient? Create an account</summary><form @submit.prevent="register"><label>Full name</label><input v-model="registerForm.full_name" required><label>Email</label><input v-model="registerForm.email" type="email" required><label>Phone</label><input v-model="registerForm.phone"><label>Password (8+ characters)</label><input v-model="registerForm.password" type="password" minlength="8" required><button class="secondary full">Create patient account</button></form></details><p v-if="error" class="alert error">{{error}}</p></div><p class="auth-bottom">Your care information deserves thoughtful protection.</p></section></main>
  <main v-else class="app-shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">✚</span> CarePoint</div><div class="workspace-label">HOSPITAL WORKSPACE</div><div class="profile"><div class="avatar">{{user?.full_name?.slice(0,1)||'C'}}</div><div><strong>{{user?.full_name}}</strong><small>{{user?.role||user?.roles?.[0]||'Member'}}</small></div><span class="online"></span></div><nav><button v-for="n in nav" :key="n.id" :class="{selected:active===n.id}" @click="active=n.id"><span class="nav-icon">{{({overview:'◫',doctors:'✚',appointments:'▦',patients:'♙',departments:'⌘',availability:'◷',profile:'♙'})[n.id]}}</span>{{n.label}}<span v-if="n.id==='appointments'" class="nav-count">{{appointments.length}}</span></button></nav><div class="sidebar-bottom"><div class="help-card"><span>✦</span><strong>Care, in sync.</strong><p>One workspace for every step of the patient journey.</p></div><button class="logout" @click="logout">↪ &nbsp; Sign out</button><small class="version">CAREPOINT HMS · 1.0</small></div></aside><section class="main-area"><header class="topbar"><div><p class="eyebrow">HOSPITAL MANAGEMENT / {{active.toUpperCase()}}</p><h1>{{({overview:'Good day, '+(user?.full_name || 'there'),doctors:'Find your care team',appointments:'Appointments',patients:'Patient directory',departments:'Departments',availability:'My availability',profile:'My profile'})[active]}}</h1></div><div class="top-actions"><span class="secure-pill">♧ Secure workspace</span><div class="avatar small-avatar">{{user?.full_name?.slice(0,1)}}</div></div></header><div v-if="error" class="alert error">{{error}}</div><div v-if="notice" class="alert success">{{notice}}</div><div v-if="busy" class="loading">Refreshing your workspace…</div>
  <template v-if="active==='overview'"><section class="welcome-banner"><div><p class="eyebrow light">YOUR CARE, ORGANIZED</p><h2>Every detail, in<br>the right place.</h2><p>From finding a specialist to managing upcoming visits, stay on top of what matters.</p><button class="banner-button" @click="active='doctors'">Explore doctors <span>→</span></button></div><div class="banner-graphic"><div class="circle circle-one"></div><div class="circle circle-two"></div><div class="cross-large">✚</div><div class="float-card"><span class="float-icon">✓</span><div><strong>Care coordinated</strong><small>Appointments made simple</small></div></div></div></section><div class="section-heading"><div><h2>Your overview</h2><p>A clear view of your hospital activity.</p></div><span class="date-chip">● &nbsp; Live workspace</span></div><div class="stats-grid"><article class="stat-card"><div class="stat-top"><span>Appointments</span><span class="stat-icon teal">▦</span></div><strong>{{appointments.length}}</strong><small>{{isAdmin?'Across the hospital':'In your schedule'}}</small></article><article class="stat-card"><div class="stat-top"><span>Available doctors</span><span class="stat-icon blue">✚</span></div><strong>{{doctors.filter(d=>d.available).length}}</strong><small>Ready to see patients</small></article><article class="stat-card"><div class="stat-top"><span>Departments</span><span class="stat-icon purple">⌘</span></div><strong>{{departments.length}}</strong><small>Specialties in one place</small></article><article class="stat-card"><div class="stat-top"><span>Scheduled</span><span class="stat-icon amber">◷</span></div><strong>{{appointments.filter(a=>a.status==='scheduled').length}}</strong><small>Upcoming visits</small></article></div><div class="content-grid"><section class="panel"><div class="panel-head"><div><h3>Upcoming appointments</h3><p>Your latest scheduled visits</p></div><button class="text-button" @click="active='appointments'">View all →</button></div><div v-if="!appointments.length" class="empty"><div class="empty-icon">▦</div><strong>No appointments yet</strong><p>Explore available doctors and book your first visit.</p><button class="secondary" @click="active='doctors'">Find a doctor</button></div><div v-else class="appointment-list"><div v-for="a in appointments.slice(0,4)" :key="a.id" class="appointment-row"><div class="date-block"><strong>{{new Date(a.scheduled_at).getDate()}}</strong><small>{{new Date(a.scheduled_at).toLocaleString('en',{month:'short'})}}</small></div><div class="appointment-info"><strong>{{a.doctor_name}}</strong><small>{{a.reason||'General consultation'}} · {{new Date(a.scheduled_at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}}</small></div><span class="status" :class="a.status">{{a.status}}</span></div></div></section><section class="panel tip-panel"><div class="tip-icon">✦</div><p class="eyebrow">A LITTLE REMINDER</p><h3>Your health<br>comes first.</h3><p>Booking ahead helps your care team prepare for your visit. You can manage scheduled appointments from your workspace.</p><button class="text-button" @click="active='appointments'">Manage appointments →</button></section></div></template>
  <template v-else-if="active==='doctors'"><div class="section-heading"><div><h2>Meet your specialists</h2><p>Choose an available doctor to schedule a visit.</p></div><span class="date-chip">{{doctors.length}} doctors</span></div><div v-if="isAdmin" class="panel form-panel"><h3>Add a doctor</h3><form class="inline-form" @submit.prevent="addDoctor"><input v-model="doctorForm.full_name" placeholder="Doctor name" required><input v-model="doctorForm.specialization" placeholder="Specialization" required><input v-model="doctorForm.phone" placeholder="Phone"><select v-model="doctorForm.department_id"><option value="">No department</option><option v-for="d in departments" :key="d.id" :value="d.id">{{d.name}}</option></select><input v-model="doctorForm.account_email" type="email" placeholder="Doctor login email (optional)"><input v-model="doctorForm.account_password" type="password" minlength="12" placeholder="Temporary password (12+ chars)"><button class="primary">Add doctor</button></form></div><div class="doctor-grid"><article v-for="d in doctors" :key="d.id" class="doctor-card"><form v-if="editingDoctor===d.id" class="edit-form" @submit.prevent="saveDoctor(d)"><h3>Edit doctor</h3><label>Name<input v-model="doctorEdit.full_name" required maxlength="120"></label><label>Specialization<input v-model="doctorEdit.specialization" required maxlength="120"></label><label>Phone<input v-model="doctorEdit.phone" maxlength="30"></label><label>Department<select v-model="doctorEdit.department_id"><option value="">No department</option><option v-for="dep in departments" :key="dep.id" :value="dep.id">{{dep.name}}</option></select></label><label class="check-row"><input v-model="doctorEdit.available" type="checkbox"> Available for bookings</label><div class="edit-actions"><button class="primary">Save changes</button><button type="button" class="secondary" @click="editingDoctor=null">Cancel</button></div></form><template v-else><div class="doctor-card-top"><div class="doctor-avatar">{{d.full_name.split(' ').map(x=>x[0]).slice(0,2).join('')}}</div><span class="availability" :class="{unavailable:!d.available}">{{d.available?'Available':'Unavailable'}}</span></div><h3>{{d.full_name}}</h3><p class="speciality">{{d.specialization}}</p><p class="doctor-dept">⌘ &nbsp; {{d.department_name||'General care'}}</p><div class="doctor-footer"><button class="primary" :disabled="!d.available" @click="active='appointments';appointmentForm.doctor_id=d.id">Book visit <span>→</span></button><button v-if="isAdmin" class="icon-button edit-icon" title="Edit doctor" @click="startEditDoctor(d)">✎</button><button v-if="isAdmin" class="icon-button danger-text" title="Delete doctor" @click="deleteDoctor(d)">⌫</button></div></template></article><div v-if="!doctors.length" class="empty wide"><strong>No doctors added yet</strong><p>An administrator can add doctors to the directory.</p></div></div></template>
  <template v-else-if="active==='appointments'"><div class="section-heading"><div><h2>Your appointments</h2><p>Book and keep track of hospital visits.</p></div></div><section class="panel form-panel"><h3>Schedule a visit</h3><form class="booking-form" @submit.prevent="bookAppointment"><label>Doctor<select v-model="appointmentForm.doctor_id" required><option value="" disabled>Select a specialist</option><option v-for="d in doctors.filter(x=>x.available)" :key="d.id" :value="d.id">{{d.full_name}} — {{d.specialization}}</option></select></label><label>Date and time<input v-model="appointmentForm.scheduled_at" type="datetime-local" required></label><label class="full-field">Reason for visit<input v-model="appointmentForm.reason" maxlength="500" placeholder="Briefly describe your concern"></label><button class="primary">Confirm appointment <span>→</span></button></form></section><section class="panel table-panel"><div class="panel-head"><div><h3>Appointment records</h3><p>{{appointments.length}} record(s)</p></div><div class="head-actions"><button v-if="isAdmin" class="secondary" @click="runReminders">✉ Send due reminders</button><button class="secondary" @click="loadAll">↻ Refresh</button></div></div><div class="table-wrap"><table><thead><tr><th>Doctor</th><th v-if="isAdmin">Patient</th><th>Date & time</th><th>Reason</th><th>Status</th><th>Action</th></tr></thead><tbody><tr v-for="a in appointments" :key="a.id"><td><strong>{{a.doctor_name}}</strong></td><td v-if="isAdmin">{{a.patient_name}}</td><td>{{new Date(a.scheduled_at).toLocaleString()}}</td><td>{{a.reason||'—'}}</td><td><span class="status" :class="a.status">{{a.status}}</span></td><td><button v-if="a.status==='scheduled' && (isAdmin || isDoctor || user?.role==='patient' || user?.roles?.includes('patient'))" class="text-button danger-text" @click="updateAppointment(a,'cancelled')">Cancel</button><button v-if="canTreat && a.status==='scheduled'" class="text-button" @click="updateAppointment(a,'completed')">Complete</button><button v-if="canTreat && (a.status==='scheduled' || a.status==='completed')" class="text-button" @click="openTreatment(a)">Treatment</button><button v-else-if="a.status==='completed'" class="text-button" @click="openTreatment(a)">History</button><span v-if="a.status!=='scheduled' && !canTreat && a.status!=='completed'" class="muted">—</span></td></tr><tr v-if="!appointments.length"><td :colspan="isAdmin?6:5" class="table-empty">No appointments found. Book a visit to get started.</td></tr></tbody></table></div></section><section v-if="treatmentAppointment" class="panel form-panel"><div class="panel-head"><div><h3>Treatment record · {{treatmentAppointment.patient_name}}</h3><p>{{treatmentAppointment.doctor_name}} · {{new Date(treatmentAppointment.scheduled_at).toLocaleString()}}</p></div><button class="secondary" @click="treatmentAppointment=null">Close</button></div><form v-if="canTreat" class="booking-form" @submit.prevent="saveTreatment"><label class="full-field">Diagnosis<input v-model="treatmentForm.diagnosis" maxlength="1000" required placeholder="Clinical diagnosis"></label><label class="full-field">Prescription<input v-model="treatmentForm.prescription" maxlength="2000" placeholder="Medication and instructions"></label><label class="full-field">Notes<input v-model="treatmentForm.notes" placeholder="Additional clinical notes"></label><button class="primary">Save treatment record</button></form><div v-if="treatmentRecords.length" class="appointment-list"><h3>Previous treatment records</h3><article v-for="t in treatmentRecords" :key="t.id" class="appointment-row"><div class="appointment-info"><strong>{{t.diagnosis}}</strong><small>{{t.prescription||'No prescription recorded'}} · {{t.created_at}}</small><small>{{t.notes}}</small></div></article></div><p v-else-if="!treatmentRecords.length" class="muted">No treatment records for this appointment yet.</p></section></template>
  <template v-else-if="active==='availability'"><div class="section-heading"><div><h2>Manage your availability</h2><p>Set the hours when patients can book appointments with you.</p></div></div><section class="panel form-panel"><h3>Add an availability window</h3><form class="booking-form" @submit.prevent="addAvailability"><label>Date<input v-model="availabilityForm.date" type="date" required></label><label>Start time<input v-model="availabilityForm.start_time" type="time" required></label><label>End time<input v-model="availabilityForm.end_time" type="time" required></label><button class="primary">Save availability</button></form></section><section class="panel table-panel"><div class="panel-head"><div><h3>Your availability windows</h3><p>Appointments can be booked within these windows when configured.</p></div><button class="secondary" @click="loadAll">↻ Refresh</button></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Start</th><th>End</th><th>Action</th></tr></thead><tbody><tr v-for="slot in availability" :key="slot.id"><td>{{slot.date}}</td><td>{{slot.start_time}}</td><td>{{slot.end_time}}</td><td><button class="text-button danger-text" @click="deleteAvailability(slot)">Remove</button></td></tr><tr v-if="!availability.length"><td colspan="4" class="table-empty">No availability windows yet.</td></tr></tbody></table></div></section></template>
  <template v-else-if="active==='profile'"><div class="section-heading"><div><h2>Your patient profile</h2><p>Keep your contact details up to date.</p></div></div><section class="panel form-panel"><h3>Personal details</h3><form class="booking-form" @submit.prevent="saveProfile"><label class="full-field">Full name<input v-model="profileForm.full_name" required maxlength="120"></label><label>Phone<input v-model="profileForm.phone" maxlength="30"></label><label>Date of birth<input v-model="profileForm.date_of_birth" type="date"></label><button class="primary">Save profile</button></form></section></template>
  <template v-else-if="active==='patients'"><div class="section-heading"><div><h2>Patient directory</h2><p>Patient profiles registered with the hospital.</p></div></div><section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Patient</th><th>Email</th><th>Phone</th><th>Action</th></tr></thead><tbody><tr v-for="p in patients" :key="p.id"><td><strong>{{p.full_name}}</strong></td><td>{{p.email||'—'}}</td><td>{{p.phone||'—'}}</td><td><button class="text-button danger-text" @click="deletePatient(p)">Delete</button></td></tr><tr v-if="!patients.length"><td colspan="4" class="table-empty">No patient profiles found.</td></tr></tbody></table></div></section></template>
  <template v-else-if="active==='departments'"><div class="section-heading"><div><h2>Hospital departments</h2><p>Specialties and services across the hospital.</p></div></div><section class="panel form-panel"><h3>Add a department</h3><form class="inline-form" @submit.prevent="addDepartment"><input v-model="departmentForm.name" placeholder="Department name" required><input v-model="departmentForm.description" placeholder="Description"><button class="primary">Add department</button></form></section><div class="department-grid"><article v-for="d in departments" :key="d.id" class="panel department-card"><form v-if="editingDepartment===d.id" class="edit-form" @submit.prevent="saveDepartment(d)"><h3>Edit department</h3><label>Name<input v-model="departmentEdit.name" required maxlength="120"></label><label>Description<input v-model="departmentEdit.description"></label><div class="edit-actions"><button class="primary">Save changes</button><button type="button" class="secondary" @click="editingDepartment=null">Cancel</button></div></form><template v-else><div class="stat-icon purple">⌘</div><h3>{{d.name}}</h3><p>{{d.description||'Hospital specialty and services.'}}</p><button class="text-button" @click="startEditDepartment(d)">Edit department</button><button class="text-button danger-text" @click="deleteDepartment(d)">Delete department</button></template></article></div></template>
  <footer class="page-footer"><span>© CarePoint Hospital Management</span><span>Built for coordinated, patient-first care</span></footer></section></main>
</template>
